After LR symmetry breaking, the $W_{R}^{3}$ and $X_{(B-L)}$ gauge states mix and
give rise to the massive $Z_{R}$ and massless (hypercharge) $B$ bosons.

Subsequently, all fermions with $(B-L)$ charges, including $\nu_L$ and $N_R$, couple to $\ZR$.

For chiral fermion $f$, we parametrize the $\ZR$ neutral currents by
\begin{eqnarray}
 \mathcal{L}_{\ZR-f-f} &=& \frac{-\kappa_{R}^f g}{\sqrt{1 - \left(1/\kappa_{R}^f\right)^2\tWSq}}\sum_{f=u,e,\dots}
 \overline{f} Z_{R \mu} \gamma^\mu \left(g_{L}^{\ZR,f}P_L + g_{R}^{\ZR,f}P_R\right)f.
\label{neucurrent}
\end{eqnarray}
$\kappa_{R}^{f}$ are the same $\kappa_{R}^{q,\ell}$ as for $\WR$.
In terms of electric and isospin charges, the chiral coefficients are
\begin{eqnarray}
 g_{L}^{\ZR,f} &=& \left(T_{L}^{3,f} - Q^f\right)\frac{1}{\kappa_{R}^{f~2}}\tWSq,
 \\
 g_{R}^{\ZR,f} &=& T_{R}^{3,f} - \frac{1}{\kappa_{R}^{f~2}}\tWSq Q^f.
\end{eqnarray}
SU$(2)_L$, SU$(2)_R$, and U$(1)_{\rm EM}$ quantum number assignments for $f$ are summarize in Tbl.~\ref{tb:qNumbers}.

For generic $\kappa_R^{q,\ell}$ normalizations, the LO $\WR,\ZR$ partial decay widths are then
\begin{eqnarray}
 \Gam{\WR \rightarrow q\overline{q'}} 	&=& N_c \vert V^{\rm{CKM'}}_{qq'}\vert^2 \frac{\kappa_{R}^{q 2} g^2 \MWR}{48 \pi}
 \\
 \Gam{\WR \rightarrow tb} 	&=& N_c \vert V^{\rm{CKM'}}_{tb}\vert^2 \frac{\kappa_{R}^{q 2} g^2 \MWR}{48 \pi}
					    \left(1-r_t^{\WR}\right)^2\left(1+\frac{1}{2}r_t^{\WR}\right),
 \\
 \Gam{\WR \rightarrow \ell N_{m'}} 	&=&     \vert Y_{\ell N_{m'}}\vert^2 \frac{\kappa_{R}^{\ell 2} g^2 \MWR}{48 \pi}
					\left(1-r_N^{\WR}\right)^2\left(1+\frac{1}{2}r_N^{\WR}\right),
\\
 \Gam{\ZR\rightarrow f\overline{f}} &=&   
 N_c^f 
 \cfrac{\kappa_{\ZR}^{f 2} g^2 \MZR \sqrt{1-4r_f^{\ZR}}}{48\pi\left[1 - (1/\kappa_{R}^f)^2\tWSq\right]}
 \nonumber\\
 &\times&
 \left[(g_{L}^{\ZR,f}+g_{R}^{\ZR,f})^2(1+2r_f^{\ZR})+(g_{L}^{\ZR,f}-g_{R}^{\ZR,f})^2(1-4r_f^{\ZR})\right]
 \\
 r_i^{V_R} &=& \frac{m_{i}^2}{M_{V_R}^2}.
\end{eqnarray}
Assuming diagonal quark mixing and lepton mixing in Eq.~(\ref{eq:lrsmNuMixing}), the total $\WR,\ZR$ widths are then
\begin{eqnarray}
 \Gamma_{\WR} &=& 2\Gam{\WR \rightarrow q\overline{q'}} + \Gam{\WR \rightarrow tb} 
 + \Gam{\WR \rightarrow e N_{1}} + \Gam{\WR \rightarrow \mu N_{2}} + \Gam{\WR \rightarrow \tau N_{3}}
 \\
 \Gamma_{\ZR} &=& \sum_{f} \Gam{\ZR\rightarrow f\overline{f}}
\end{eqnarray}

